// Maps next/image width requests to the files generated by scripts/images.mjs.
// Only /assets/photos/<name>.webp has variants; anything else is returned as-is
// (pass `unoptimized` on those images so Next does not build a srcset for them).
const PHOTO = /^\/assets\/photos\/([a-z-]+)\.webp$/;
const VARIANT_WIDTHS = [640, 960];

export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  const match = PHOTO.exec(src);
  if (!match) return src;
  const variant = VARIANT_WIDTHS.find((w) => w >= width);
  return variant ? `/assets/photos/${match[1]}-${variant}.webp` : src;
}
